 if(u<700)ultPose(a,'ultA',u);else if(u<1400){state='ultA';index=5;}else if(u<1650){state='run';index=Math.floor((u-1400)/70)%data.run.length;}else if(u<2400)ultPose(a,'ultB',u-1650);else if(u<3200)ultPose(a,'ultC',u-2400);else if(u<4600)ultPose(a,'ultD',u-3200);else{state='riff';index=u<4800?8:9;}
