 if(local<1500){a.stage='B';index=6+phase({visual:'entranceB',time:local});if(index>=8&&!a.chordPlayed){a.chordPlayed=true;try{playRiff();}catch(e){}}if(index>=11&&!a.stomp){a.stomp=true;playMuscleImpact();}}
